/// <summary>
/// PricingAttribute of table <c>InventTable</c> field grossHeight.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableGrossHeight extends UPSPricingAttributeInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, grossHeight);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Real);
    InventTable inventTable;
    while select grossHeight from inventTable
        group by grossHeight
    {
        ret.add(inventTable.grossHeight);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTable, grossHeight));
    qbr.value(queryValue(_value));
}
